void abort(void);
void exit(int);

int main(void) {
  struct {
    signed int   s : 3;
    unsigned int u : 3;
    int          i : 3;
  } x = {-1, -1, -1};

  if (x.u != 7)
    abort();
  if (x.s != -1)
    abort();

  if (x.i != -1 && x.i != 7)
    abort();

  exit(0);
}


